#nullable enable // autogenerated

using MVZ2.Vanilla.Localization;
using PVZEngine.Definitions;
using PVZEngine.Level;
using PVZEngine.SeedPacks;

namespace MVZ2.GameContent.Recharges
{
    [AutoRechargeDefinition(VanillaRechargeNames.VeryShortTime)]
    public class VeryShortRecharge : RechargeDefinition
    {
        public VeryShortRecharge(string nsp, string name) : base(nsp, name)
        {
            SetProperty(EngineRechargeProps.START_MAX_RECHARGE, 0);
            SetProperty(EngineRechargeProps.MAX_RECHARGE, 90);
            SetProperty(EngineRechargeProps.QUALITY, 1);
            SetProperty(EngineRechargeProps.NAME, VanillaStrings.RECHARGE_VERY_SHORT);
        }
    }
}
